begin;
do $x$ begin if not exists (select 1 from public.places where book_id='ulisse' and id='clongowes' and abs(latitude-53.310917)<0.000001 and abs(longitude-(-6.683444))<0.000001) then raise exception 'Coordinate mismatch: clongowes'; end if; if exists (select 1 from public.place_references where book_id='ulisse' and id='3:core:clongowes' and (place_id<>'clongowes' or category<>'action')) then raise exception 'Reference conflict: clongowes'; end if; end $x$;
update public.place_descriptions set metadata=jsonb_set(metadata,'{positionDescription,texts}','{"it":"Collegio gesuita presso Clane, nella contea di Kildare, frequentato da Stephen negli anni di scuola.","en":"The Jesuit college near Clane, County Kildare, attended by Stephen in his schooldays.","fr":"Collège jésuite près de Clane, dans le comté de Kildare, fréquenté par Stephen pendant ses années d’école.","es":"Colegio jesuita cerca de Clane, en el condado de Kildare, al que asistió Stephen durante sus años escolares."}'::jsonb,true) where book_id='ulisse' and place_id='clongowes' and collection='core';
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:clongowes',3,'clongowes','core',5,'action','In a brief recollected scene Stephen puts his face in water at Clongowes and feels fear; the campus is the geographic location, not a separate interior.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict (book_id,id) do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:clongowes:original',3,'3:core:clongowes','original','en','original','I would try. I am not a strong swimmer. Water cold soft. When I put my face into it in the basin at Clongowes. Can’t see! Who’s behind me? Out quickly, quickly!','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Clongowes"],"reviewedAt":"2026-11-10"}'::jsonb) on conflict (book_id,id) do nothing;
do $x$ begin if not exists (select 1 from public.places where book_id='ulisse' and id='ship' and abs(latitude-53.34867)<0.000001 and abs(longitude-(-6.258728))<0.000001) then raise exception 'Coordinate mismatch: ship'; end if; if exists (select 1 from public.place_references where book_id='ulisse' and id='3:core:ship' and (place_id<>'ship' or category<>'mentioned')) then raise exception 'Reference conflict: ship'; end if; end $x$;
update public.place_descriptions set metadata=jsonb_set(metadata,'{positionDescription,texts}','{"it":"The Ship era un albergo e una taverna al 5 di Lower Abbey Street; il punto fa riferimento al sito dell’indirizzo storico.","en":"The Ship was a hotel and tavern at 5 Lower Abbey Street; the point refers to the site of that historical address.","fr":"The Ship était un hôtel et une taverne au 5 Lower Abbey Street ; le point indique le site de cette adresse historique.","es":"The Ship era un hotel y una taberna en el número 5 de Lower Abbey Street; el punto señala el sitio de esa dirección histórica."}'::jsonb,true) where book_id='ulisse' and place_id='ship' and collection='core';
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:ship',3,'ship','core',6,'mentioned','Stephen remembers the planned half-past-twelve meeting at The Ship; he is still on the strand and no scene at the tavern is narrated here.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict (book_id,id) do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:ship:original',3,'3:core:ship','original','en','original','I mustn’t forget his letter for the press. And after? The Ship, half twelve. By the way go easy with that money like a good young imbecile. Yes, I must.','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["The Ship"],"reviewedAt":"2026-11-10"}'::jsonb) on conflict (book_id,id) do nothing;
do $x$ begin if not exists (select 1 from public.places where book_id='ulisse' and id='tower' and abs(latitude-53.288656)<0.000001 and abs(longitude-(-6.113632))<0.000001) then raise exception 'Coordinate mismatch: tower'; end if; if exists (select 1 from public.place_references where book_id='ulisse' and id='3:core:tower' and (place_id<>'tower' or category<>'mentioned')) then raise exception 'Reference conflict: tower'; end if; end $x$;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:tower',3,'tower','core',7,'mentioned','Stephen thinks of the tower while looking south from the strand; the present scene remains on the shore.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict (book_id,id) do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:tower:original',3,'3:core:tower','original','en','original','Turning, he scanned the shore south, his feet sinking again slowly in new sockets. The cold domed room of the tower waits. Through the barbacans the shafts of light are moving ever, slowly ever as my feet are sinking, creeping duskward over the dial floor. Blue dusk, nightfall, deep blue night.','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["tower"],"reviewedAt":"2026-11-10"}'::jsonb) on conflict (book_id,id) do nothing;
commit;
